package io.github.jesterportfolio.hearth.survival;

import java.util.*;
import java.util.concurrent.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;
import org.bukkit.event.*;
import org.bukkit.event.player.*;
import org.bukkit.event.inventory.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.block.*;
import net.kyori.adventure.text.Component;
import io.github.jesterportfolio.hearth.network.*;

/** 일반 생존 실행 경로. RPG 세션/전투/인벤토리 복원 모듈을 등록하지 않습니다. */
public final class SurvivalRuntime implements Listener,AutoCloseable {
    public enum Phase{STARTING,READY,DRAINING,DRAINED,HOLD,CLOSED}
    private io.github.jesterportfolio.hearth.survival.economy.SurvivalEconomy economy;
    public io.github.jesterportfolio.hearth.survival.economy.SurvivalEconomy economy(){return Objects.requireNonNull(economy);}
    private record Link(Player player,Object token){}
    private record Move(Link link,Location origin,Location target){}
    private final JavaPlugin plugin;private final SurvivalSettings settings;private final SurvivalWorlds worlds;private final WorldTravel travel;private final PaperWorldMenu menu;private final PaperNetwork network;private final Map<UUID,Link> links=new HashMap<>();private final Set<Object> frozen=Collections.newSetFromMap(new IdentityHashMap<>());private final Map<UUID,Move> moves=new HashMap<>();private final BukkitTask pulse;private final NamespacedKey owner,legacyOwner;private volatile Phase phase=Phase.STARTING;
    public SurvivalRuntime(JavaPlugin plugin)throws Exception {
        this.plugin=plugin;if(plugin.getConfig().getBoolean("market-automation.enabled")&&!plugin.getConfig().getBoolean("survival-economy.enabled"))throw new IllegalArgumentException("MARKET_REQUIRES_SURVIVAL_ECONOMY");var networkSettings=BackendAuthentication.settings(plugin,"economy");BackendAuthentication.require(networkSettings);if(!Bukkit.getOnlinePlayers().isEmpty())throw new IllegalStateException("SURVIVAL_EXISTING_PLAYERS");
        var section=Objects.requireNonNull(plugin.getConfig().getConfigurationSection("survival-runtime"));var values=new HashMap<String,Object>(section.getValues(false));var nested=new HashMap<String,Object>();var definitions=Objects.requireNonNull(section.getConfigurationSection("worlds"));for(var role:SurvivalWorld.values())nested.put(role.id(),Objects.requireNonNull(definitions.getConfigurationSection(role.id())).getValues(false));values.put("worlds",nested);settings=SurvivalSettings.parse(values);owner=new NamespacedKey(plugin,"survival_group");legacyOwner=new NamespacedKey(plugin,"economy_inventory_realm");worlds=new SurvivalWorlds(plugin,settings);travel=new WorldTravel(action->Bukkit.getScheduler().runTask(plugin,action),System::currentTimeMillis);
        menu=new PaperWorldMenu(plugin,new PaperWorldMenu.Boundary(){public Object token(Player p){var l=links.get(p.getUniqueId());return l!=null&&SurvivalRuntime.this.available(p)?l.token():null;}public boolean current(Player p,Object token){return same(p,token)&&SurvivalRuntime.this.available(p);}public SurvivalWorld world(Player p){return worlds.role(p.getWorld());}public boolean available(Player p,SurvivalWorld target){return SurvivalRuntime.this.available(p)&&worlds.worlds().containsKey(target);}public void select(Player p,Object token,SurvivalWorld target){selectWorld(p,token,target);}});
        network=networkSettings==null?null:new PaperNetwork(plugin,networkSettings,new PaperNetwork.Boundary(){public Object token(Player p){var l=links.get(p.getUniqueId());return l!=null&&SurvivalRuntime.this.available(p)?l.token():null;}public boolean current(Player p,Object token){return same(p,token)&&!p.isDead();}public void freeze(Player p,Object token,boolean value){if(value){if(!same(p,token)||!available(p)||p.isInsideVehicle()||!p.getPassengers().isEmpty()||!frozen.add(token))throw new IllegalStateException("SURVIVAL_TRANSFER_BUSY");}else frozen.remove(token);}public CompletionStage<Void> save(Player p,Object token){try{if(!same(p,token)||p.isDead())throw new IllegalStateException("SURVIVAL_TRANSFER_STALE");VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),p.getUniqueId(),p::saveData);return CompletableFuture.completedFuture(null);}catch(RuntimeException error){return CompletableFuture.failedFuture(error);}}},action->Bukkit.getScheduler().runTask(plugin,action));
        Bukkit.getPluginManager().registerEvents(this,plugin);pulse=Bukkit.getScheduler().runTaskTimer(plugin,travel::tick,20,20);
        Objects.requireNonNull(plugin.getCommand("world")).setExecutor((sender,command,label,args)->{if(sender instanceof Player p){if(args.length==0)menu.open(p);else p.sendMessage(Component.text("/월드 · 월드 선택창 열기"));}else sender.sendMessage("생존 상태="+phase);return true;});
        Objects.requireNonNull(plugin.getCommand("hearthserver")).setExecutor((sender,command,label,args)->{if(sender instanceof Player p){if(network==null)p.sendMessage(Component.text("서버 네트워크가 설정되지 않았습니다."));else network.command(p,label.equalsIgnoreCase("lobby")?"/lobby":"/hearthserver"+(args.length==1?" "+args[0]:""));}else sender.sendMessage("생존 상태="+phase);return true;});
        Objects.requireNonNull(plugin.getCommand("heartheconomy")).setExecutor((sender,command,label,args)->{if(sender instanceof org.bukkit.command.ConsoleCommandSender){if(economy==null)sender.sendMessage("생존 경제가 설정되지 않았습니다.");else economy.console(args,sender::sendMessage);}return true;});
        try{worlds.prepare().thenCompose(v->{if(!plugin.getConfig().getBoolean("survival-economy.enabled"))return CompletableFuture.<Void>completedFuture(null);try{economy=new io.github.jesterportfolio.hearth.survival.economy.SurvivalEconomy(plugin,settings.group(),new io.github.jesterportfolio.hearth.survival.economy.SurvivalEconomy.Boundary(){public Object token(Player p){var l=links.get(p.getUniqueId());return l!=null&&l.player()==p?l.token():null;}public boolean current(Player p,Object token){return same(p,token);}public boolean available(Player p){return baseAvailable(p);}public void freeze(Player p,Object token,boolean value){if(value){if(!same(p,token)||p.isDead()||!frozen.add(token))throw new IllegalStateException("NATIVE_ECONOMY_FREEZE");}else if(same(p,token))frozen.remove(token);}public void hold(){phase=Phase.HOLD;}public Map<SurvivalWorld,World> worlds(){return worlds.worlds();}});return economy.ready();}catch(Exception error){return CompletableFuture.<Void>failedFuture(error);}}).whenComplete((ignored,error)->{if(phase!=Phase.STARTING)return;if(error!=null){phase=Phase.HOLD;plugin.getLogger().log(java.util.logging.Level.SEVERE,"HEARTH_SURVIVAL_HOLD",error);}else{phase=Phase.READY;plugin.getLogger().info("HEARTH_SURVIVAL_READY worlds=3 inventory=native");}});}catch(Exception failure){phase=Phase.HOLD;plugin.getLogger().log(java.util.logging.Level.SEVERE,"HEARTH_SURVIVAL_HOLD",failure);}
        Objects.requireNonNull(plugin.getCommand("hearthsurvivaladmin")).setExecutor((sender,command,label,args)->{if(!(sender instanceof org.bukkit.command.ConsoleCommandSender))return true;if(args.length==1&&args[0].equals("drain")){drain().whenComplete((v,error)->sender.sendMessage(error==null?"생존 저장·종료 준비 완료":"진행 중 저장/거래를 확인하세요."));}else if(args.length==1&&args[0].equals("verify")){try{io.github.jesterportfolio.hearth.verification.SurvivalVerification.run(plugin,this);}catch(Exception failure){plugin.getLogger().log(java.util.logging.Level.SEVERE,"HEARTH_SURVIVAL_PROBE FAIL",failure);}}else sender.sendMessage("생존 상태="+phase+" 월드="+worlds.worlds().size());return true;});
    }
    public CompletionStage<Void> drain(){if(economy==null){phase=Phase.DRAINING;for(var p:List.copyOf(Bukkit.getOnlinePlayers()))p.kick(Component.text("생존 서버 종료 준비"));phase=Phase.DRAINED;return CompletableFuture.completedFuture(null);}var work=economy.drain();if(economy.phase()==io.github.jesterportfolio.hearth.survival.economy.SurvivalEconomy.Phase.DRAINING)phase=Phase.DRAINING;return work.thenRunAsync(()->phase=Phase.DRAINED,action->Bukkit.getScheduler().runTask(plugin,action));}
    private boolean same(Player p,Object token){var l=links.get(p.getUniqueId());return phase==Phase.READY&&l!=null&&l.player()==p&&l.token()==token&&p.isOnline()&&Bukkit.getPlayer(p.getUniqueId())==p;}
    private boolean available(Player p){return baseAvailable(p)&&(economy==null||!economy.busy(p));}
    private boolean baseAvailable(Player p){var l=links.get(p.getUniqueId());return l!=null&&same(p,l.token())&&!p.isDead()&&!frozen.contains(l.token())&&!travel.busy(p.getUniqueId())&&!moves.containsKey(p.getUniqueId())&&(network==null||network.phase(p.getUniqueId()).isEmpty());}
    private boolean blocked(Player p){var l=links.get(p.getUniqueId());return phase!=Phase.READY||l==null||l.player()!=p||frozen.contains(l.token());}
    private void selectWorld(Player p,Object token,SurvivalWorld role){if(!same(p,token)||!available(p)||p.isInsideVehicle()||!p.getPassengers().isEmpty()){p.sendMessage(Component.text("탑승·사망·다른 이동 처리가 끝난 뒤 다시 이용하세요."));return;}var link=links.get(p.getUniqueId());var origin=p.getLocation().clone();
        try{travel.begin(p.getUniqueId(),token,role,new WorldTravel.Port(){Move move;public boolean current(){return same(p,token)&&!p.isDead();}public boolean atOrigin(){return p.getWorld()==origin.getWorld()&&p.getLocation().distanceSquared(origin)<.01;}public void freeze(boolean value){if(value)frozen.add(token);else frozen.remove(token);}public CompletionStage<Object> prepare(SurvivalWorld target){try{var entry=worlds.entry(target);move=new Move(link,origin,entry);return CompletableFuture.completedFuture(move);}catch(RuntimeException invalid){return CompletableFuture.failedFuture(invalid);}}public CompletionStage<Boolean> move(Object prepared){if(prepared!=move||!current()||!atOrigin())return CompletableFuture.failedFuture(new IllegalStateException("WORLD_MOVE_STALE"));if(moves.putIfAbsent(p.getUniqueId(),move)!=null)throw new IllegalStateException("WORLD_NATIVE_MOVE_PENDING");var future=p.teleportAsync(move.target().clone(),PlayerTeleportEvent.TeleportCause.PLUGIN);future.whenComplete((ok,error)->Bukkit.getScheduler().runTask(plugin,()->moves.remove(p.getUniqueId(),move)));return future;}public boolean atTarget(Object prepared){return prepared==move&&p.getWorld()==move.target().getWorld()&&p.getLocation().distanceSquared(move.target())<.01;}public void notice(String code){if(same(p,token))p.sendMessage(Component.text(code.equals("WORLD_MOVE_COMPLETE")?role.label()+"로 이동했습니다.":code.equals("WORLD_TARGET_UNAVAILABLE")||code.equals("WORLD_MOVE_REFUSED")?"안전한 도착 지점이 없어 이동하지 않았습니다.":"월드 이동 보류 · 재접속 후 상태를 확인하세요."));}});}catch(RuntimeException failure){p.sendMessage(Component.text("현재는 월드를 이동할 수 없습니다."));}
    }
    @EventHandler public void join(PlayerJoinEvent event){var p=event.getPlayer();String group=p.getPersistentDataContainer().get(owner,PersistentDataType.STRING);if(phase!=Phase.READY||!p.isWhitelisted()||links.containsKey(p.getUniqueId())||p.getPersistentDataContainer().has(legacyOwner)||group!=null&&!settings.group().toString().equals(group)){p.kick(Component.text("생존 서버 입장 보류 · 기존 소유권 데이터를 확인하세요."));return;}p.getPersistentDataContainer().set(owner,PersistentDataType.STRING,settings.group().toString());links.put(p.getUniqueId(),new Link(p,new Object()));if(economy!=null)economy.admit(p);p.sendMessage(Component.text("/월드 · 거주 / 야생 / 지옥 선택"));}
    @EventHandler public void death(PlayerDeathEvent event){var p=event.getEntity();var old=links.get(p.getUniqueId());if(old==null||old.player()!=p)return;if(economy!=null)economy.invalidate(p);boolean pending=frozen.contains(old.token())||travel.busy(p.getUniqueId())||moves.containsKey(p.getUniqueId())||(network!=null&&network.phase(p.getUniqueId()).isPresent());var next=new Link(p,new Object());links.put(p.getUniqueId(),next);frozen.remove(old.token());travel.quit(p.getUniqueId(),old.token());if(pending){frozen.add(next.token());p.sendMessage(Component.text("저장·이동 중 생명 상태 변경 · 재접속 후 확인하세요."));}}
    @EventHandler public void respawn(PlayerRespawnEvent event){if(economy!=null)Bukkit.getScheduler().runTask(plugin,()->{var p=event.getPlayer();var l=links.get(p.getUniqueId());if(phase==Phase.READY&&l!=null&&l.player()==p&&p.isOnline()&&!p.isDead())economy.admit(p);});}
    @EventHandler public void quit(PlayerQuitEvent event){var p=event.getPlayer();var link=links.get(p.getUniqueId());if(link!=null&&link.player()==p){if(economy!=null)economy.invalidate(p);links.remove(p.getUniqueId(),link);frozen.remove(link.token());travel.quit(p.getUniqueId(),link.token());/* native teleport future retains its tombstone until completion */}}
    @EventHandler(priority=EventPriority.HIGHEST) public void teleport(PlayerTeleportEvent event){var p=event.getPlayer();var move=moves.get(p.getUniqueId());if(move!=null){var to=event.getTo();boolean permit=event.getCause()==PlayerTeleportEvent.TeleportCause.PLUGIN&&same(p,move.link().token())&&!p.isDead()&&travel.moving(p.getUniqueId(),move.link().token(),move)&&to!=null&&to.getWorld()==move.target().getWorld()&&to.distanceSquared(move.target())<.01&&SurvivalWorlds.safe(to);if(!permit)event.setCancelled(true);}else if(blocked(p))event.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void portal(PlayerPortalEvent event){if(blocked(event.getPlayer()))event.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void move(PlayerMoveEvent event){if(!(event instanceof PlayerTeleportEvent)&&blocked(event.getPlayer()))event.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void command(PlayerCommandPreprocessEvent event){if(blocked(event.getPlayer()))event.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(e.getWhoClicked() instanceof Player p&&blocked(p))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getWhoClicked() instanceof Player p&&blocked(p))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void drop(PlayerDropItemEvent e){if(blocked(e.getPlayer()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void pickup(EntityPickupItemEvent e){if(e.getEntity() instanceof Player p&&blocked(p))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void interact(PlayerInteractEvent e){if(blocked(e.getPlayer()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void damage(EntityDamageEvent e){if(e.getEntity() instanceof Player p&&blocked(p))e.setCancelled(true);if(e instanceof EntityDamageByEntityEvent hit){var attacker=hit.getDamager();if(attacker instanceof Player p&&blocked(p)||attacker instanceof org.bukkit.entity.Projectile projectile&&projectile.getShooter() instanceof Player shooter&&blocked(shooter))e.setCancelled(true);}}
    @EventHandler(priority=EventPriority.HIGHEST) public void place(BlockPlaceEvent e){if(blocked(e.getPlayer()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void breakBlock(BlockBreakEvent e){if(blocked(e.getPlayer()))e.setCancelled(true);}
    public boolean aiPreparationRecorded(){return economy!=null&&economy.aiPreparationRecorded();}
    public Phase phase(){return phase;}public SurvivalWorlds worlds(){return worlds;}
    @Override public void close(){boolean clean=phase==Phase.DRAINED||economy==null&&phase==Phase.READY;phase=Phase.CLOSED;pulse.cancel();if(economy!=null)economy.close();menu.close();if(network!=null)network.close();travel.close();for(var link:links.values())if(link.player().isOnline())link.player().kick(Component.text("생존 서버 종료"));HandlerList.unregisterAll(this);worlds.close();links.clear();frozen.clear();plugin.getLogger().info("HEARTH_SURVIVAL_DISABLE_CLOSE "+(clean?"PASS":"HOLD"));}
}
